mapper.sql:
where 1=1

		and cpta_llave = #{llaveTabla}


		and cpta_estado = #{estado}


		and dpta_fecha >= #{fechaMin}


		and dpta_fecha  <   #{fechaMax}


		and cpta_transicion = #{transicion}


		and cpta_propiedad = #{propiedad}


		and dpta_ejecucion >= #{ejecucionMin}


		and dpta_ejecucion  <   #{ejecucionMax}
